public class PaymentProcessorFactory {
    public PaymentProcessor createProcessor(String type) {
        if(type.equals("paypal")) return new PaypalPaymentProcessor();
        if(type.equals("credit")) return new CreditCardPaymentProcessor();
        if(type.equals("debit")) return new DebitCardPaymentProcessor();
        throw new IllegalArgumentException("Unknown payment type");
    }
}
